<script setup lang="ts">
import { ref, watch, computed, onBeforeUnmount } from 'vue'
import { message, Modal } from 'ant-design-vue'
import { onBeforeRouteLeave } from 'vue-router'
import { getPerson, getEmployeeMetadata, previewLink, linkUser, createUser, transferEmployee, disableUser, resetTemporaryPassword } from '@/services/iamPeople'
import { getWorkSubject } from '@/services/iamWork'
import { canIam, iamMessage } from '@/services/iamAccess'
import type { EmployeeDetail, EmployeeMetadata, OwnershipEvidence } from '@/types/iam'
import OwnAccountVerification from '@/components/account/OwnAccountVerification.vue'
import { useAccountProof } from '@/composables/useAccountProof'
import AppUsageList from './AppUsageList.vue'
import WorkSettings from './WorkSettings.vue'
const props = withDefaults(defineProps<{ open: boolean; employeeId: string; initialTab?: string; initialApp?: string | null }>(), { initialTab: 'basic', initialApp: null })
const emit = defineEmits<{ close: []; changed: [] }>()
const person = ref<EmployeeDetail | null>(null), metadata = ref<EmployeeMetadata | null>(null), tab = ref('basic'), editingApp = ref<string | null>(null), loading = ref(true), busy = ref(false), error = ref(''), secret = ref('')
const settings = ref<InstanceType<typeof WorkSettings> | null>(null), apps = ref<InstanceType<typeof AppUsageList> | null>(null)
const action = ref(''), targetUser = ref(''), department = ref(''), evidence = ref('')
const proof = useAccountProof(() => { secret.value = '' })
let generation = 0, requestId = ''
const employee = computed(() => person.value?.employee), capabilities = computed(() => ({ link: canIam('iam.people.link'), provision: canIam('iam.people.provision'), transfer: canIam('iam.people.transfer'), disable: canIam('iam.people.disable'), reset: canIam('iam.people.reset') }))
async function load() { const run = ++generation; loading.value = true; error.value = ''; try { const detail:EmployeeDetail = canIam('iam.people.read') ? await getPerson(props.employeeId) : await getWorkSubject(props.employeeId,props.initialApp||'attendance').then(data=>({employee:data.employee,account:{user_id:data.account.user_id},association:{employee_id:data.employee.id,user_id:data.account.user_id},history:[],configuration_only:true})); if (run === generation) { person.value = detail; if (!detail.employee.user_id) editingApp.value = null } } catch (e) { if (run === generation) { person.value = null; error.value = iamMessage(e) } } finally { if (run === generation) loading.value = false } }
async function close() { if (busy.value || (settings.value && !await settings.value.requestLeave())) return false; if (action.value && (evidence.value || targetUser.value)) { const leave = await new Promise<boolean>(resolve => Modal.confirm({ title: '放弃尚未提交的账号操作？', okText: '放弃', cancelText: '继续填写', onOk: () => resolve(true), onCancel: () => resolve(false) })); if (!leave) return false }; secret.value = ''; proof.invalidate(); emit('close'); return true }
async function begin(kind: string) { action.value = kind; requestId = ''; evidence.value = ''; targetUser.value = ''; department.value = ''; secret.value = ''; error.value = ''; proof.invalidate(); if (kind === 'transfer') try { metadata.value = await getEmployeeMetadata() } catch(e) { error.value = iamMessage(e) } }
function ownership(): OwnershipEvidence { return { employee_number: employee.value!.employee_number, company: employee.value!.company, account_user_id: action.value === 'create' ? person.value!.account.proposed_user_id || '' : targetUser.value, reference: evidence.value.trim() } }
async function execute() {
  if (!employee.value || busy.value || !proof.valid.value || proof.method.value !== 'password') return
  if (['create','link'].includes(action.value) && evidence.value.trim().length < 12) { error.value = '请填写至少12个字的明确归属核验依据；姓名相同不能作为归属证明。'; return }
  if (action.value === 'link' && !targetUser.value.trim()) { error.value = '请输入已有账号的原始 User 主键。'; return }
  if (action.value === 'transfer' && !department.value) { error.value = '请选择现有目标部门。'; return }
  busy.value = true; error.value = ''
  try {
    let linkVersion = employee.value.version
    if (action.value === 'link') linkVersion = (await previewLink(employee.value.id, targetUser.value, ownership())).version
    const confirmed = await new Promise<boolean>(resolve => Modal.confirm({ title: '确认执行本次员工账号操作？', content: `${employee.value!.name}（工号 ${employee.value!.employee_number}）。服务端将重新校验管理范围、归属和版本。`, okText: '确认执行一次', cancelText: '返回核对', onOk: () => resolve(true), onCancel: () => resolve(false) }))
    if (!confirmed) return
    requestId ||= crypto.randomUUID()
    const row = employee.value
    const result = action.value === 'create' ? await createUser(row.id, ownership(), row.version, requestId) : action.value === 'link' ? await linkUser(row.id, targetUser.value, ownership(), linkVersion, requestId) : action.value === 'transfer' ? await transferEmployee(row.id, department.value, row.version, requestId) : action.value === 'disable' ? await disableUser(row.id, row.version, requestId) : await resetTemporaryPassword(row.id, row.version, requestId)
    proof.invalidate(); secret.value = result.temporary_password || ''; action.value = ''; evidence.value = ''; targetUser.value = ''; await load(); message.success('员工账号操作已完成。'); emit('changed')
  } catch (e) { error.value = iamMessage(e) } finally { busy.value = false }
}
watch(() => [props.open,props.employeeId], () => { generation++; person.value = null; secret.value = ''; action.value = ''; proof.invalidate(); if (props.open && props.employeeId) { tab.value = props.initialTab; editingApp.value = props.initialApp; void load() } }, { immediate: true })
onBeforeRouteLeave(()=>props.open?close():true)
onBeforeUnmount(()=>{generation++;secret.value='';proof.invalidate()})
</script>
<template><a-drawer :open="open" :width="'min(800px, 100vw)'" :title="employee ? `${employee.name} · 员工资料` : '员工资料'" :mask-closable="false" :body-style="{padding:'24px'}" @close="close"><div class="employee-drawer"><a-alert v-if="error" :message="error" type="warning" show-icon /><a-skeleton v-if="loading" active /><template v-else-if="person && employee">
  <WorkSettings v-if="editingApp" ref="settings" subject-kind="employee" :subject-id="employeeId" :app-id="editingApp" @back="editingApp = null" @saved="emit('changed')" />
  <template v-else><div class="employee-heading"><strong>{{ employee.name }}</strong><span>工号 {{ employee.employee_number }}</span><a-tag>{{ employee.account_status === 'unopened' ? '未开通账号' : employee.account_status === 'disabled' ? '账号已停用' : '已开通账号' }}</a-tag></div><a-tabs v-model:activeKey="tab"><a-tab-pane key="basic" tab="员工资料"><a-descriptions :column="1"><a-descriptions-item label="公司">{{ employee.company }}</a-descriptions-item><a-descriptions-item label="主部门">{{ employee.department_name }}</a-descriptions-item><a-descriptions-item label="岗位">{{ employee.position || '待补充' }}</a-descriptions-item><a-descriptions-item label="考勤关联">{{ employee.attendance_status === 'confirmed' ? '已确认' : '待确认' }}</a-descriptions-item></a-descriptions><details v-if="!person.configuration_only"><summary>身份与业务关联</summary><a-descriptions :column="1"><a-descriptions-item label="Employee 主键">{{ employee.id }}</a-descriptions-item><a-descriptions-item label="原始工号">{{ employee.employee_number }}</a-descriptions-item><a-descriptions-item label="User 主键">{{ person.association.user_id || '尚未关联' }}</a-descriptions-item><a-descriptions-item label="登录别名">{{ person.account.username || '未设置' }}</a-descriptions-item><a-descriptions-item label="飞书">{{ person.account.feishu_bound ? '已绑定' : '未绑定' }}</a-descriptions-item><a-descriptions-item label="考勤身份核验">{{ employee.attendance_status === 'confirmed' ? '明确关联已确认' : '等待核验，不按姓名认领' }}</a-descriptions-item></a-descriptions></details></a-tab-pane>
    <a-tab-pane v-if="canIam('iam.access.read')" key="apps" tab="应用安排"><p v-if="!employee.user_id" class="aux">尚未开通账号，以下只展示当前部门安排。完成开户后再设置个人工作。</p><AppUsageList ref="apps" :employee-id="employeeId" :configuration-app-id="person.configuration_only ? initialApp || 'attendance' : undefined" :can-edit="Boolean(employee.user_id) && canIam('iam.access.manage')" @modify="appId => editingApp = appId" /></a-tab-pane>
    <a-tab-pane v-if="!person.configuration_only" key="account" tab="账号管理"><p>管理员协助操作单独核验。员工本人的登录与安全由本人在“我的与设置”维护。</p><div class="account-actions"><a-button v-if="!employee.user_id && capabilities.provision" @click="begin('create')">为已有员工开户</a-button><a-button v-if="!employee.user_id && capabilities.link" @click="begin('link')">关联已有账号</a-button><a-button v-if="capabilities.transfer" @click="begin('transfer')">调整主部门</a-button><a-button v-if="employee.user_id && capabilities.reset" @click="begin('reset')">受控重置临时密码</a-button><a-button v-if="employee.user_id && employee.account_status !== 'disabled' && capabilities.disable" danger @click="begin('disable')">停用此员工账号</a-button></div>
      <section v-if="secret" class="secret"><strong>本次临时密码，仅当次显示</strong><a-input-password :value="secret" readonly autocomplete="off" /><p>请私下交付已核验本人；关闭抽屉后不能重新读取。</p><a-button @click="secret = ''">已交付，隐藏</a-button></section>
      <section v-if="action" class="command-form"><h3>{{ ({create:'为已有员工开户',link:'关联已有账号',transfer:'调整主部门',disable:'停用账号',reset:'重置临时密码'} as Record<string,string>)[action] }}</h3><OwnAccountVerification password-only @verified="proof.sync" @invalidated="proof.invalidate" /><a-form layout="vertical" @submit.prevent="execute"><a-form-item v-if="action === 'link'" label="已有账号的 User 主键"><a-input v-model:value="targetUser" :disabled="busy" autocomplete="off" /></a-form-item><a-form-item v-if="action === 'create' || action === 'link'" label="明确归属核验依据" help="填写核验记录编号与依据，至少12字；不要填写口令或验证码。"><a-textarea v-model:value="evidence" :disabled="busy" :maxlength="500" /></a-form-item><a-form-item v-if="action === 'transfer'" label="目标主部门"><a-select v-model:value="department" :disabled="busy" :options="metadata?.departments" /></a-form-item><p v-if="action === 'transfer'">个人特别安排保留，部门继承安排按新部门重新计算；历史考勤仍归原 Employee。</p><p v-if="action === 'disable'">仅停用此员工账号，并撤销相关会话；员工档案和历史业务记录保留。</p><a-button :disabled="busy" @click="action = ''; proof.invalidate()">取消</a-button><a-button type="primary" html-type="submit" :loading="busy" :disabled="!proof.valid.value || proof.method.value !== 'password'">核对并执行</a-button></a-form></section>
    </a-tab-pane><a-tab-pane v-if="!person.configuration_only" key="history" tab="变更记录"><a-empty v-if="!person.history.length" description="暂无可见的脱敏变更记录" /><p v-for="(event,index) in person.history" :key="index">{{ event.occurred_at }} · {{ event.operation }} · {{ event.reason }}</p></a-tab-pane></a-tabs></template>
</template><a-button v-if="!loading && !person" @click="load">重试读取</a-button></div></a-drawer></template>
<style scoped>.employee-drawer{font-size:16px;line-height:1.6;display:grid;gap:16px;min-width:0}.employee-heading{display:flex;flex-wrap:wrap;align-items:center;gap:12px}.employee-heading strong{font-size:22px;overflow-wrap:anywhere}.employee-heading span,.aux{font-size:14px;color:var(--hbos-text-secondary)}.account-actions{display:flex;flex-wrap:wrap;gap:12px}.command-form,.secret{margin-top:20px;padding:20px;background:#f4f8f5;border:1px solid #d6e3da;border-radius:12px}.secret{display:grid;gap:12px}.command-form .ant-btn+.ant-btn{margin-left:12px}summary{cursor:pointer;font-weight:600;margin:16px 0}.employee-drawer :deep(.ant-descriptions-item-content){overflow-wrap:anywhere;font-size:16px}.employee-drawer :deep(.ant-descriptions-item-label){font-size:14px}</style>
